<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import Icon from './Icon.vue';
import CustomerPicker from './CustomerPicker.vue';
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
type Contact={id:string;customerId:string;customerName:string;name:string;jobTitle:string;phone:string;email:string;primary:boolean;description:string;version:number;canWrite:boolean;canRelink:boolean;updatedAt:string};
type Lead={id:string;name:string;companyName:string;industry:string;source:string;region:string;jobTitle:string;phone:string;email:string;description:string;ownerMemberId:string;ownerName:string;status:string;version:number;canWrite:boolean;canConvert:boolean;convertedCustomerId:string|null;convertedCustomerName:string|null;convertedContactId:string|null;convertedAt:string|null;updatedAt:string};
type Page<T>={items:T[];total:number;page:number;pageSize:number};
const props=withDefaults(defineProps<{section:string;request:Request;readonly:boolean;write:boolean;memberId?:string;customerId?:string;opportunityWrite?:boolean}>(),{opportunityWrite:false,customerId:''});
const emit=defineEmits<{customer:[id:string];contacts:[customerId:string];clearFilter:[];opportunity:[value:{id:string;customerId:string;title:string}]}>();
const contacts=computed(()=>props.section==='contacts');
const contactRows=ref<Contact[]>([]),leadRows=ref<Lead[]>([]),total=ref(0),page=ref(1),q=ref(''),status=ref('');
const busy=ref(false),error=ref(''),success=ref(''),dialog=ref(''),editor=ref<Contact|Lead|null>(null),key=ref('');
const owners=ref<{id:string;name:string}[]>([]),conversionOwners=ref<{id:string;name:string}[]>([]),lastConversion=ref<Lead|null>(null);
const stateNames:Record<string,string>={NEW:'新线索',CONTACTED:'已联系',QUALIFIED:'已确认合格',UNQUALIFIED:'不合格',CONVERTED:'已转客户'};
const transitions:Record<string,string[]>={NEW:['NEW','CONTACTED','UNQUALIFIED'],CONTACTED:['CONTACTED','QUALIFIED','UNQUALIFIED'],QUALIFIED:['QUALIFIED','CONTACTED','UNQUALIFIED'],UNQUALIFIED:['UNQUALIFIED','NEW'],CONVERTED:['CONVERTED']};
const form=reactive({customerId:'',customerName:'',name:'',jobTitle:'',phone:'',email:'',primary:false,description:'',companyName:'',industry:'制造业',source:'官网咨询',region:'',ownerMemberId:'',status:'NEW',convertMode:'new',convertName:'',convertLevel:'B',convertOwner:'',convertCustomer:'',convertPrimary:false});
const contactEditor=computed(()=>contacts.value?editor.value as Contact|null:null),leadEditor=computed(()=>!contacts.value?editor.value as Lead|null:null);
const canSave=computed(()=>!props.readonly&&(editor.value?editor.value.canWrite:props.write));
const availableStates=computed(()=>transitions[leadEditor.value?.status??'NEW']??['NEW']);
const modal=ref<HTMLElement|null>(null);let focus:HTMLElement|null=null,previousOverflow:string|null=null;
function restoreScroll(){if(previousOverflow!==null){document.body.style.overflow=previousOverflow;previousOverflow=null;}}
function close(){if(!busy.value)dialog.value='';}
watch(dialog,async value=>{if(value){focus=document.activeElement as HTMLElement;if(previousOverflow===null)previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled)')?.focus({preventScroll:true});}else{restoreScroll();focus?.focus({preventScroll:true});}});
function keys(event:KeyboardEvent){if(!dialog.value)return;if(event.key==='Escape'){close();return;}if(event.key==='Tab'){const nodes=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
onMounted(()=>document.addEventListener('keydown',keys));onUnmounted(()=>{document.removeEventListener('keydown',keys);restoreScroll();});
function date(value:string){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';const status=(e as {status?:number})?.status;if(status===403||status===404){dialog.value='';editor.value=null;contactRows.value=[];leadRows.value=[];lastConversion.value=null;total.value=0;}}finally{busy.value=false;}}
async function load(){const path=`page=${page.value}&pageSize=20&q=${encodeURIComponent(q.value)}`;
 if(contacts.value){const data=await props.request<Page<Contact>>('/contacts?'+path+(props.customerId?'&customerId='+encodeURIComponent(props.customerId):''));contactRows.value=data.items;total.value=data.total;}
 else{const data=await props.request<Page<Lead>>('/leads?'+path+'&status='+status.value);leadRows.value=data.items;total.value=data.total;}
}
function find(){page.value=1;success.value='';lastConversion.value=null;return run(load);}
function filter(value:string){status.value=value;return find();}
function turn(delta:number){page.value+=delta;return run(load);}
function reset(){Object.assign(form,{customerId:props.customerId,customerName:'',name:'',jobTitle:'',phone:'',email:'',primary:false,description:'',companyName:'',industry:'制造业',source:'官网咨询',region:'',ownerMemberId:'',status:'NEW'});success.value='';lastConversion.value=null;key.value=crypto.randomUUID();}
function open(item?:{id:string}){return run(async()=>{
 reset();editor.value=null;
 if(contacts.value){
  if(item){const c=await props.request<Contact>('/contacts/'+item.id);editor.value=c;Object.assign(form,c);}
  else if(props.customerId){const c=await props.request<{name:string}>('/customers/'+props.customerId);form.customerName=c.name;}
  dialog.value='contact';
 }else{
  if(item){const l=await props.request<Lead>('/leads/'+item.id);editor.value=l;Object.assign(form,l);}
  if(!props.readonly&&props.write)owners.value=await props.request<typeof owners.value>('/leads/owners');
  if(!item)form.ownerMemberId=owners.value.find(m=>m.id===props.memberId)?.id??owners.value[0]?.id??'';
  dialog.value='lead';
 }
});}
function createOpportunity(l:Lead){if(l.convertedCustomerId){close();emit('opportunity',{id:l.id,customerId:l.convertedCustomerId,title:l.companyName+' · 新商机'});}}
function save(){return run(async()=>{
 const path=contacts.value?'/contacts':'/leads';
 const input=contacts.value?{customerId:form.customerId,name:form.name,jobTitle:form.jobTitle,phone:form.phone,email:form.email,primary:form.primary,description:form.description}:{name:form.name,companyName:form.companyName,industry:form.industry,source:form.source,region:form.region,jobTitle:form.jobTitle,phone:form.phone,email:form.email,description:form.description,ownerMemberId:form.ownerMemberId};
 if(editor.value)await props.request(path+'/'+editor.value.id,'PATCH',{...input,expectedVersion:editor.value.version,...(!contacts.value?{status:form.status}:{})});
 else await props.request(path,'POST',input,{'Idempotency-Key':key.value});
 dialog.value='';page.value=1;await load();success.value=contacts.value?'联系人已保存到数据库':'线索已保存到数据库';
});}
function openConvert(item:Lead){return run(async()=>{
 const l=await props.request<Lead>('/leads/'+item.id);if(!l.canConvert)throw new Error('转换需要合格线索，以及线索、客户和联系人写入权限');
 conversionOwners.value=await props.request<typeof conversionOwners.value>('/customers/owners');editor.value=l;key.value=crypto.randomUUID();success.value='';
 Object.assign(form,{convertMode:'new',convertName:l.companyName,convertLevel:'B',convertOwner:conversionOwners.value.find(m=>m.id===l.ownerMemberId)?.id??conversionOwners.value[0]?.id??'',convertCustomer:'',convertPrimary:false});dialog.value='convert';
});}
function convert(){return run(async()=>{
 if(!leadEditor.value)return;
 const input={expectedVersion:leadEditor.value.version,primaryContact:form.convertMode==='new'||form.convertPrimary,...(form.convertMode==='new'?{customerName:form.convertName,customerLevel:form.convertLevel,ownerMemberId:form.convertOwner}:{targetCustomerId:form.convertCustomer})};
 const result=await props.request<Lead>('/leads/'+leadEditor.value.id+'/convert','POST',input,{'Idempotency-Key':key.value});
 dialog.value='';status.value='CONVERTED';page.value=1;await load();lastConversion.value=result;success.value='线索已关联客户并生成联系人，原线索保留为只读记录';
});}
watch(()=>[props.section,props.customerId],()=>{page.value=1;q.value='';status.value='';contactRows.value=[];leadRows.value=[];total.value=0;success.value='';lastConversion.value=null;run(load);},{immediate:true});
</script>
<template>
 <section class="business-workspace">
  <div class="page-heading"><div><span class="eyebrow">{{contacts?'CUSTOMER RELATIONSHIPS':'LEAD WORKSPACE'}}</span><h1>{{contacts?'联系人':'线索中心'}}</h1><p>{{contacts?'维护客户联系人，访问范围跟随所属客户。':'记录潜在需求，联系并确认合格后转为客户。'}}</p></div><button v-if="write&&!readonly" class="btn primary" :disabled="busy" @click="open()"><Icon name="plus" :size="17"/>{{contacts?'新增联系人':'新增线索'}}</button></div>
  <div v-if="readonly" class="business-alert warning">当前企业为只读状态，可以查看已有资料。</div>
  <div v-if="error&&!dialog" class="business-alert error" role="alert">{{error}}</div>
  <div v-if="success" class="business-alert ok" role="status"><span>{{success}}</span><div v-if="lastConversion?.convertedCustomerId" class="business-actions"><button class="text-button" @click="emit('customer',lastConversion.convertedCustomerId)">查看客户</button><button v-if="lastConversion.convertedContactId" class="text-button" @click="emit('contacts',lastConversion.convertedCustomerId)">查看联系人</button><button v-if="opportunityWrite&&!readonly" class="text-button" @click="createOpportunity(lastConversion!)">创建来源商机</button></div></div>
  <div v-if="contacts&&customerId" class="business-filter-note"><Icon name="building" :size="18"/><span>当前显示此客户的联系人</span><button class="text-button" :disabled="busy" @click="emit('clearFilter')">查看全部联系人</button></div>
  <div v-if="!contacts" class="business-state-tabs" aria-label="筛选线索状态"><button :class="{active:status===''}" :disabled="busy" @click="filter('')">全部线索</button><button v-for="(name,value) in stateNames" :key="value" :class="{active:status===value}" :disabled="busy" @click="filter(value)">{{name}}</button></div>
  <section class="card business-data-card"><form class="business-toolbar" @submit.prevent="find"><div class="business-search"><Icon name="search" :size="18"/><input v-model="q" :placeholder="contacts?'姓名、客户、电话或邮箱':'公司、姓名、电话或邮箱'" :aria-label="contacts?'搜索联系人':'搜索线索'" maxlength="100"/><button class="btn secondary" :disabled="busy">搜索</button></div><span>共 {{total}} 条</span><button type="button" class="icon-button" :aria-label="contacts?'刷新联系人':'刷新线索'" :disabled="busy" @click="run(load)"><Icon name="refresh"/></button></form>
   <div class="table-scroll"><table v-if="contacts"><thead><tr><th>联系人</th><th>所属客户</th><th>电话 / 邮箱</th><th>主要联系人</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="c in contactRows" :key="c.id"><td><strong>{{c.name}}</strong><small>{{c.jobTitle||'职位未填写'}}</small></td><td><button class="text-button" :disabled="busy" @click="emit('customer',c.customerId)">{{c.customerName}}</button></td><td>{{c.phone||'—'}}<small>{{c.email||'—'}}</small></td><td><span v-if="c.primary" class="badge green">主要联系人</span><span v-else>—</span></td><td>{{date(c.updatedAt)}}</td><td><button class="text-button" :disabled="busy" @click="open(c)">{{c.canWrite?'查看 / 编辑':'查看资料'}}</button></td></tr><tr v-if="!contactRows.length"><td colspan="6" class="empty-cell">{{busy?'正在加载…':'暂无可见联系人，可以先新增客户并关联联系人'}}</td></tr></tbody></table>
    <table v-else><thead><tr><th>公司 / 联系人</th><th>联系方式</th><th>来源</th><th>状态</th><th>负责人</th><th>操作</th></tr></thead><tbody><tr v-for="l in leadRows" :key="l.id"><td><strong>{{l.companyName}}</strong><small>{{l.name}} {{l.jobTitle?'· '+l.jobTitle:''}}</small></td><td>{{l.phone||'—'}}<small>{{l.email||'—'}}</small></td><td>{{l.source}}</td><td><span class="badge" :class="l.status==='QUALIFIED'||l.status==='CONVERTED'?'green':'neutral'">{{stateNames[l.status]}}</span></td><td>{{l.ownerName}}</td><td><div class="business-actions"><button class="text-button" :disabled="busy" @click="open(l)">{{l.canWrite?'查看 / 编辑':'查看资料'}}</button><button v-if="l.canConvert&&!readonly" class="text-button" :disabled="busy" @click="openConvert(l)">转为客户<Icon name="arrow" :size="14"/></button></div></td></tr><tr v-if="!leadRows.length"><td colspan="6" class="empty-cell">{{busy?'正在加载…':'当前筛选下没有可见线索'}}</td></tr></tbody></table></div>
   <div class="business-pagination"><span>第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div>
  </section>
  <div class="business-note"><strong>{{contacts?'联系人权限':'线索推进'}}</strong><p>{{contacts?'客户共享、转交或角色变化后，后续请求会重新检查联系人访问权限。主要联系人每个客户最多一位。':'新线索 → 已联系 → 已确认合格 → 转为客户。不合格线索可以重新开启；已转换线索保留为只读来源记录。'}}</p></div>
  <Teleport to="body"><div v-if="dialog" class="modal-backdrop" @click.self="close"><section ref="modal" class="business-dialog" role="dialog" aria-modal="true" aria-labelledby="business-dialog-title"><header class="business-dialog-heading"><div><h2 id="business-dialog-title">{{dialog==='convert'?'将线索转为客户':editor?(contacts?'联系人资料':'线索资料'):(contacts?'新增联系人':'新增线索')}}</h2><p v-if="dialog==='convert'">{{leadEditor?.companyName}} · {{leadEditor?.name}}</p></div><button class="icon-button" :disabled="busy" aria-label="关闭资料窗口" @click="close"><Icon name="close"/></button></header>
   <form class="business-dialog-form" @submit.prevent="dialog==='convert'?convert():save()"><div class="business-dialog-body">
    <fieldset :disabled="busy||dialog!=='convert'&&!canSave">
     <template v-if="dialog==='convert'"><div class="business-convert-note"><strong>转换后会保留原线索</strong><p>客户关联、联系人创建和线索状态同时保存。新增客户会占用套餐的客户额度。</p></div><div class="business-radio-options"><label><input v-model="form.convertMode" type="radio" value="new"/>新建客户</label><label><input v-model="form.convertMode" type="radio" value="existing"/>关联已有客户</label></div><div v-if="form.convertMode==='new'" class="business-form-grid"><label class="wide">客户名称<input v-model="form.convertName" required maxlength="200"/></label><label>客户等级<select v-model="form.convertLevel"><option>A</option><option>B</option><option>C</option></select></label><label>客户负责人<select v-model="form.convertOwner" required><option value="">请选择负责人</option><option v-for="m in conversionOwners" :key="m.id" :value="m.id">{{m.name}}</option></select></label></div><template v-else><div class="business-field"><strong>选择客户</strong><CustomerPicker v-model="form.convertCustomer" :request="request" :disabled="busy"/></div><label class="business-checkbox"><input v-model="form.convertPrimary" type="checkbox"/>将生成的联系人设为主要联系人</label><p class="business-helper">勾选后会替换该客户当前的主要联系人。</p></template></template>
     <div v-else class="business-form-grid">
      <div v-if="contacts" class="business-field wide"><strong>所属客户</strong><CustomerPicker v-model="form.customerId" :selected-name="form.customerName" :request="request" :disabled="!canSave||busy||!!contactEditor&&!contactEditor.canRelink"/><small v-if="contactEditor&&!contactEditor.canRelink">线索转换生成的联系人保留原客户关联。</small></div>
      <label v-else class="wide">公司名称<input v-model="form.companyName" required maxlength="200"/></label>
      <label>联系人姓名<input v-model="form.name" required maxlength="100"/></label><label>职位<input v-model="form.jobTitle" maxlength="100" placeholder="如：采购经理"/></label>
      <label>电话<input v-model="form.phone" type="tel" maxlength="40" placeholder="如：+86 13800000000"/></label><label>邮箱<input v-model="form.email" type="email" maxlength="254" placeholder="如：name@example.com"/></label>
      <template v-if="!contacts"><label>行业<input v-model="form.industry" required maxlength="80"/></label><label>来源<input v-model="form.source" required maxlength="80"/></label><label>地区<input v-model="form.region" maxlength="100"/></label><label>负责人<select v-model="form.ownerMemberId" required><option value="">请选择负责人</option><option v-if="leadEditor&&!owners.some(m=>m.id===leadEditor?.ownerMemberId)" :value="leadEditor.ownerMemberId">{{leadEditor.ownerName}}</option><option v-for="m in owners" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label v-if="editor" class="wide">线索状态<select v-model="form.status"><option v-for="state in availableStates" :key="state" :value="state">{{stateNames[state]}}</option></select></label></template>
      <label class="wide">{{contacts?'联系人备注':'线索备注'}}<textarea v-model="form.description" rows="4" maxlength="4000"></textarea></label><label v-if="contacts" class="business-checkbox wide"><input v-model="form.primary" type="checkbox"/>设为该客户的主要联系人</label>
     </div>
    </fieldset>
    <div v-if="leadEditor?.status==='CONVERTED'&&dialog!=='convert'" class="business-conversion-result"><strong>已转换 · 原线索只读</strong><p v-if="leadEditor.convertedCustomerName">客户：{{leadEditor.convertedCustomerName}}</p><p v-else>关联客户需有当前访问权限才能查看。</p><p v-if="leadEditor.convertedAt">转换时间：{{date(leadEditor.convertedAt)}}（上海时间）</p><button v-if="leadEditor.convertedCustomerId" type="button" class="text-button" :disabled="busy" @click="close();emit('customer',leadEditor.convertedCustomerId)">查看关联客户</button><button v-if="leadEditor.convertedCustomerId&&opportunityWrite&&!readonly" type="button" class="text-button" :disabled="busy" @click="createOpportunity(leadEditor)">创建来源商机</button></div>
    <div v-if="error" class="business-alert error" role="alert">{{error}}</div>
   </div><footer class="business-dialog-footer"><small>{{dialog==='convert'?'确认后生成客户关联和联系人':canSave?'保存时检查当前权限和记录版本':'当前资料为只读'}}</small><button type="button" class="btn secondary" :disabled="busy" @click="close">{{canSave||dialog==='convert'?'取消':'关闭'}}</button><button v-if="canSave||dialog==='convert'" class="btn primary" :disabled="busy">{{busy?'正在保存…':dialog==='convert'?'确认转换':contacts?'保存联系人':'保存线索'}}</button></footer></form>
  </section></div></Teleport>
 </section>
</template>
